INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 24, 'theory', 'Quiz: Messenger');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 24, 0, 'How is the order of messages in a chat set?', '["By the time they reach the server", "By a number assigned sequentially in one place for each chat", "Randomly", "Alphabetically"]', 1, 'Arrival time is not stable: we need a number within the chat, which is why a chat belongs to one shard.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 24, 1, 'How do you avoid duplicates when a message is resent on a bad network?', '["Forbid resends", "The client generates a message ID and the server drops repeats by it", "Send less often", "Delete old messages"]', 1, 'At-least-once delivery plus idempotency gives the effect of exactly once.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 24, 2, 'Why are messages sharded by chat ID?', '["It is simpler", "All messages of a chat sit together and are read in one query, while load is spread across chats", "To increase latency", "To store the time"]', 1, 'Sharding by time ranges would send all new messages to the last shard.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 24, 3, 'How is a message fanned out to a very large group?', '["To everyone at once in one loop", "The message is stored once, and delivery goes in portions through a queue; offline members get a push", "Only on request", "Not at all"]', 1, 'This avoids an avalanche, and the fan-out rate is limited.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 24, 4, 'What is the source of truth about message delivery?', '["The push notification", "The message state on the server: a push is only a hint", "The phone''s clock", "The recipient''s screen"]', 1, 'Push platforms are unreliable, so on opening the client catches up on history by cursor.');
